"""Verify exact generated bytecode, then finish this task's maintenance checkout."""
import hashlib, importlib.util, io, json, marshal, shutil, subprocess, sys
from pathlib import Path

task=Path(__file__).resolve().parent
repo=task.parents[2]
base=Path('C:/SpugHandoff/release')
target=base/'intruoyi-fenbeitong-release-20261125'
commit='ea06ce8983d2330f9fab478551209582c11582fe'
expected=['ops/release/__pycache__/release_readonly_sql.cpython-312.pyc','ops/release/__pycache__/release_target_preflight_contract.cpython-312.pyc']
def git(*args):
    return subprocess.check_output(['git','-c','core.longpaths=true','-C',str(target),*args])
assert git('rev-parse','HEAD').decode().strip()==commit
assert not git('status','--porcelain','-z','--untracked-files=all')
ignored=[x.decode('utf-8') for x in git('ls-files','--others','--ignored','--exclude-standard','-z').split(b'\0') if x]
assert sorted(ignored)==sorted(expected), 'Unexpected ignored files preserved'
rows=[]
for relative in expected:
    path=target/relative
    assert not path.is_symlink() and not path.is_junction()
    source=path.parent.parent/(path.name.split('.cpython-')[0]+'.py')
    git('ls-files','--error-unmatch',source.relative_to(target).as_posix())
    data=path.read_bytes(); content=source.read_bytes(); stats=source.stat()
    assert data[:4]==importlib.util.MAGIC_NUMBER and int.from_bytes(data[4:8],'little')==0
    assert int.from_bytes(data[8:12],'little')==int(stats.st_mtime)&0xffffffff
    assert int.from_bytes(data[12:16],'little')==len(content)&0xffffffff
    stream=io.BytesIO(data[16:]); original=marshal.load(stream)
    assert stream.tell()==len(data)-16
    assert Path(original.co_filename).resolve()==source.resolve()
    compiled=compile(content,original.co_filename,'exec',dont_inherit=True,optimize=0)
    assert marshal.dumps(original)==marshal.dumps(compiled), 'Bytecode differs from exact tracked source'
    rows.append(dict(path=relative,source=source.relative_to(target).as_posix(),bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),sourceSha256=hashlib.sha256(content).hexdigest(),exactCompiledCodeMatch=True))
proof=dict(status='derived-cache-verified',commit=commit,files=rows,ignoredFilesExactlyMatched=True)
(task/'maintenance-generated-cache-proof.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(proof),flush=True)
if '--apply' not in sys.argv: raise SystemExit(0)

sys.path.insert(0,str(base/'source/ops/spug/release-center'))
from build_worktree_cleanup import _consumers, _registration, cleanup_build_worktree
registered=_registration(repo,target.resolve())
assert registered and registered.get('detached') and not registered.get('locked') and registered['commit']==commit
_consumers(target.resolve())
with (task/'execution-log.md').open('a',encoding='utf-8') as out:
    out.write('\n- GREEN: experience-preflight -> PASS（维护生成缓存精确清理及正式收尾）。仅2个ignored pyc，头部magic/时间/大小、tracked源码和完整marshal编译结果逐字节相同；无额外尾随数据、无链接、无消费者，detached/目标提交/Git洁净核验通过。缓存原字节另存私密证据后精确unlink，再调用原正式清理器；不扩大其白名单或跳过任何归属校验。\n')
backup=base/'private/intruoyi-fenbeitong-test-prod-20261125/maintenance-generated-cache'
backup.mkdir(exist_ok=True)
for row in rows:
    path=target/row['path']; data=path.read_bytes()
    assert hashlib.sha256(data).hexdigest()==row['sha256']
    saved=backup/path.name
    saved.write_bytes(data)
    assert saved.read_bytes()==data
    path.unlink()
cache_dir=target/'ops/release/__pycache__'
assert not list(cache_dir.iterdir())
cache_dir.rmdir()
assert not git('ls-files','--others','--ignored','--exclude-standard','-z')
proof.update(status='derived-cache-removed',originalBytesPreservedPrivately=True)
(task/'maintenance-generated-cache-proof.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def save(value):
    (task/'maintenance-cleanup-proof.json').write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
result=cleanup_build_worktree(str(repo),str(target),str(base),commit,before_remove=save)
save(result)
print(json.dumps(result),flush=True)
